-- 0075_translate_content_it.sql
-- Фаза 28: перевод контента программ — итальянский (it).
-- Переведено вручную с русского оригинала (с опорой на вычитанный
-- английский), с терминологией, принятой в залах этой страны. Английские
-- названия упражнений (Hip Thrust, Mountain Climbers…) оставлены как есть.
-- Применять после 0072. Сопоставление — по точному русскому тексту.
-- Безопасно выполнять повторно.

update public.workout_programs p
set title_it = v.title, description_it = v.description
from (values
  ('pohudenie-zhenshchiny-doma', 'Dimagrimento · Donne · Casa', 'Dimagrimento per donne (a casa) — DonatelleX, programma annuale. Attrezzatura: Manubri, elastici di diversa resistenza, tappetino, step o piattaforma stabile (se possibile)'),
  ('pohudenie-zhenshchiny-zal', 'Dimagrimento · Donne · Palestra', 'Dimagrimento per donne (in palestra) — programma annuale. Attrezzatura: Tapis roulant, ellittica/SkiErg, macchine, manubri, cavi, tappetino'),
  ('nabor-massy-zhenshchiny-doma', 'Massa muscolare · Donne · Casa', 'Aumento della massa muscolare per donne (a casa) — programma annuale. Attrezzatura: Manubri, elastici di diversa resistenza, tappetino, step o piattaforma stabile'),
  ('nabor-massy-zhenshchiny-zal', 'Massa muscolare · Donne · Palestra', 'Aumento della massa muscolare per donne (in palestra) — programma annuale «12 LEVELS». Attrezzatura: Bilanciere, manubri, macchine (Hip Thrust, Hack Squat, Leg Press, cavi), elastici, kettlebell, TRX, palla medica'),
  ('pohudenie-muzhchiny-doma', 'Dimagrimento · Uomini · Casa', 'Dimagrimento per uomini (a casa) — programma annuale. Attrezzatura: Manubri, elastici, sbarra per trazioni (se possibile), sedia/panca, tappetino'),
  ('pohudenie-muzhchiny-zal', 'Dimagrimento · Uomini · Palestra', 'Dimagrimento per uomini (in palestra) — programma annuale. Attrezzatura: Bilanciere, manubri, macchine, cavi, Battle Rope, SkiErg/vogatore, area cardio (tapis roulant/ellittica/cyclette)'),
  ('nabor-massy-muzhchiny-doma', 'Massa muscolare · Uomini · Casa', 'Aumento della massa muscolare per uomini (a casa) — programma annuale. Attrezzatura: Manubri, elastici, sbarra per trazioni (se possibile), sedia/panca, tappetino'),
  ('nabor-massy-muzhchiny-zal', 'Massa muscolare · Uomini · Palestra', 'Aumento della massa muscolare per uomini (in palestra) — programma annuale. Attrezzatura: Palestra completa: bilancieri, manubri, macchine, sbarra, corde, TRX, kettlebell'),
  ('nabor-massy-nachinayushchim', 'Massa muscolare per principianti', 'Il primo programma per gli uomini che vogliono iniziare ad aumentare la massa muscolare in palestra. Ciclo di 7 giorni: 4 allenamenti di forza per diversi gruppi muscolari e 3 giorni di cardio leggero con addominali. Adatto ai principianti: niente tecnica complessa, focus sul volume e sulla corretta esecuzione.')
) as v(slug, title, description)
where p.slug = v.slug;

